mapper.select:
select

from personal_order po
left join `user` u on u.id = po.user_id

    po.family_id = #{familyId}
    and po.deleted = 0

        and po.meal_session_id = #{mealSessionId}


        and po.status = #{status}


        and po.user_id = #{userId}


order by po.created_at desc, po.id desc
